"""Complete vegetable, seafood and sandwich dishes with full homemade sauce options."""
import pathlib,json,sqlite3,copy
root=pathlib.Path(__file__).parent
out=root.parent.parent/'outputs/SavorShelf-Content-Repairs'
db=sqlite3.connect(out/'grouped-work.sqlite3')
rows=json.loads((out/'dressing-candidates.json').read_text(encoding='utf-8'))

records={r['sourceId']:r for r in json.loads((root/'content-overrides.json').read_text(encoding='utf-8'))}
aliases={r['id']:r for r in json.loads((root/'recipe-aliases.json').read_text(encoding='utf-8'))}
newids=[]
def src(n):return json.loads(db.execute('select record from recipes where id=?',(rows[n]['id'],)).fetchone()[0])
def I(k,a,u,n,s):return dict(key=k,amount=a,unit=u,name=n,substitution=s)
def oil(a):return I('oil',a,'ml','olive oil','Use the same volume of a mild sunflower or rapeseed oil.')
def vinegar(a,kind='white wine'):return I('vinegar',a,'ml',kind+' vinegar','Use the same volume of cider vinegar for a different flavor.')
def salt(a=.5):return I('salt',a,'tsp','fine salt','Reduce or omit to taste.')
def pepper(a=.25):return I('pepper',a,'tsp','ground black pepper','Use the same amount of ground white pepper, or omit.')
def parsley(a=1):return I('parsley',a,'tsp','fresh parsley, finely chopped','Use the same amount of finely chopped chives.')
def tk(k):return '{{'+k+'}}'
STORE='Use promptly, or cover and refrigerate at 4°C (40°F) or colder for up to 3 days. Whisk again before serving; oil and vinegar naturally separate. This is a fresh dressing, not a shelf-stable preserve.'
NOTE=' Spoon measures use the app’s modern 15 ml tablespoon and 5 ml teaspoon. Yields, missing quantities and preparation times are modern estimates, not recovered historical measurements. Not kitchen-tested. Scaling changes ingredient amounts, not preparation times.'
def add(n,title,y,t,desc,items,steps,notes):
 s=src(n);r=copy.deepcopy(s['recipe']);r.update(title=title,description=desc,category='Condiments',servings=y,yieldUnit='servings',minutes=t,totalMinutes=t,ingredients=items,steps=steps,sourceStatus='adapted',versionNote='Modern measured adaptation',updatedAt='2026-09-22T20:00:00Z',notes=notes+NOTE,source=s['recipe']['source']+' SavorShelf measured adaptation.');r.pop('variants',None);r['sourceAliases']=[]
 records[r['id']]=dict(sourceId=r['id'],bodySha256=s['bodySha256'],recipe=r);newids.append(r['id']);return r
def variant(r,id,label,items,steps):r.setdefault('variants',[]).append(dict(id=id,label=label,ingredients=items,steps=steps))
def yolks(a):return I('yolks',a,'','large pasteurized egg yolks','Use 18 g commercially pasteurized liquid egg yolk per yolk; do not substitute unpasteurized raw egg.')
def mustard(a):return I('mustard',a,'tsp','dry mustard powder','Use the same volume of prepared Dijon mustard for a milder flavor.')
def cayenne():return I('cayenne',.0625,'tsp','ground cayenne pepper','Omit for a mild mayonnaise.')
def lemon(a):return I('lemon',a,'ml','lemon juice','Use the same volume of lime juice for a different flavor.')
COLD='Transfer to a clean covered container and refrigerate immediately at 4°C (40°F) or colder. Use within 3 days, using a clean spoon each time. This is fresh homemade mayonnaise, not a shelf-stable preserve.'
def emulsion(keys):
 return ['Set a clean small bowl on a damp towel to steady it. Whisk '+', '.join(tk(k) for k in keys)+' until smooth.','Measure {{oil}} into a jug. Whisk continuously while adding it drop by drop at first. Once the mixture is thick and glossy, add the remaining measured oil in a very thin stream, whisking until fully incorporated. Stop pouring if oil pools on the surface and whisk until it blends in.','The finished mayonnaise should be smooth and creamy. If it separates, put 1 teaspoon cold drinking water in a clean bowl and whisk the separated mixture into it a few drops at a time; this small repair addition changes the yield slightly.',COLD]
def eggsource(r):r['source']+=' Raw-yolk handling uses commercially pasteurized egg: https://www.foodsafety.gov/people-at-risk .';return r
def eggs(a):return I('eggs',a,'','large eggs for hard boiling','Use large pasteurized shell eggs if preferred; cook until the yolks are firm.')
def water(a,k='water'):return I(k,a,'ml','drinking water','Use the same volume of drinking water, topping up to cover as directed.')
def boil():return ['Put {{eggs}} in a saucepan with {{water}}, adding more water only if needed to cover by about 2 cm. Bring to a boil, cover, remove from heat and stand for 12 minutes. Cool under cold running water, peel and cut open; the yolks must be firm throughout.']
END='Keep covered at 4°C (40°F) or colder until serving. Refrigerate leftovers within 2 hours and use within 2 days. Do not leave the platter at room temperature for more than 2 hours.'
REF=' Cooking endpoints: https://www.foodsafety.gov/food-safety-charts/safe-minimum-internal-temperatures . Variety meats: https://ask.fsis.usda.gov/article/What-are-the-recommended-cooking-times-for-veal .'
def finish(r):r['category']='Main dishes';r['source']+=REF;return eggsource(r)

def mayo(a):return I('mayo',a,'ml','plain prepared mayonnaise, kept refrigerated','Use the complete homemade-sauce variation below; its measured portion replaces this amount.')
def homemade(r,style='dutch'):
 amount=next(i['amount'] for i in r['ingredients'] if i['key']=='mayo')
 vi=[I('mayoreserve',amount,'ml','mayonnaise portion reserved from the homemade batch below; not an additional purchase','Use the prepared-mayonnaise base recipe for a quicker version.') if i['key']=='mayo' else copy.deepcopy(i) for i in r['ingredients']]
 mi=[I('mayoyolk',18,'g','pasteurized liquid egg yolk','Use one large commercially pasteurized shell-egg yolk, about 18 g.'),I('mayooil',175 if style=='dutch' else 240,'ml','olive oil for homemade mayonnaise','Use the same volume of sunflower oil.'),I('mayoacid',25 if style=='dutch' else 10,'ml','white wine vinegar for homemade mayonnaise','Use the same volume of lemon juice.'),I('mayomustard',3.75 if style=='dutch' else 2.5,'ml','prepared smooth mustard' if style=='dutch' else 'English mustard powder','Use the same volume of prepared English mustard; the flavor differs.'),I('mayosalt',.25 if style=='dutch' else .5,'tsp','fine salt for homemade mayonnaise','Reduce or omit.'),I('mayopepper',.0625,'tsp','ground white pepper' if style=='dutch' else 'ground cayenne pepper','Omit for a milder dressing.')]
 ms=['For the homemade sauce, whisk {{mayoyolk}}, {{mayomustard}}, {{mayosalt}} and {{mayopepper}} in a clean bowl. Measure {{mayooil}} into a jug and whisk it in drop by drop at first, then in a thin stream as the sauce thickens. Alternate the later oil additions with small additions of {{mayoacid}} until smooth. Cover and refrigerate while preparing the dish.']
 vs=[s.replace('{{mayo','{{mayoreserve') for s in r['steps']]
 vs.append('The measured mayonnaise portion in the dish is taken from the homemade batch. Refrigerate the unused mayonnaise in a separate clean covered container at 4°C (40°F) or colder and use within 3 days; use a clean spoon each time. The batch makes extra so that a whole yolk can be emulsified reliably.')
 variant(r,'homemade-mayonnaise','With homemade mayonnaise',vi+mi,ms+vs);r['notes']+=' The prepared-mayonnaise version is a modern shortcut. The complete homemade variation follows '+('half the Dutch recipe 367, making about 220 ml' if style=='dutch' else 'the Greenbaum one-yolk recipe, making about 270 ml')+' and reserves only the stated portion for this dish; unused sauce is explicitly accounted for. Allow about 15 additional minutes if making the sauce.';eggsource(r)

r=add(41,'Asparagus Tips with Mayonnaise',2,25,'Tender asparagus tips are chilled and served with a small spoonful of mayonnaise.',[I('asparagus',8,'','medium asparagus tips, the upper 8–10 cm of the spears','Use the same number of thick tips split lengthwise; cooking time may differ.'),water(750),salt(.25),mayo(30)],['Rinse {{asparagus}} and trim any tough ends. Bring {{water}} and {{salt}} to a boil in a saucepan. Add the asparagus and simmer for 2–4 minutes until tender but still holding its shape.','Drain and refresh under cold running drinking water. Drain thoroughly, pat dry and refrigerate for about 10 minutes until cold.','Arrange the cold tips on a small platter and spoon {{mayo}} over them. Serve chilled.',END],'The original eight asparagus tips are retained. Cooking water, salt, sauce amount, chilling time and two small servings are supplied modern quantities. Only the tips are part of this recipe; save the remaining stalks for soup or another dish.');r['category']='Vegetables';homemade(r)

r=add(42,'Garnalen met Mayonnaise — Dutch Shrimp Salad',2,35,'Chilled cooked shrimp are lightly seasoned with oil and vinegar, then mixed with tangy mayonnaise.',[I('shrimp',125,'g','raw peeled deveined shrimp, thawed if frozen','Use 100 g commercially cooked peeled shrimp, thawed in the refrigerator; omit the poaching step.'),water(500),I('poachsalt',2,'g','salt for poaching','Reduce or omit.'),I('dressoil',2.5,'ml','olive oil for seasoning the shrimp','Use the same volume of sunflower oil.'),I('dressvinegar',2.5,'ml','white wine vinegar for seasoning the shrimp','Use the same volume of lemon juice.'),pepper(.0625),mayo(30)],['Bring {{water}} and {{poachsalt}} to a gentle simmer. Add {{shrimp}} and poach for about 2–4 minutes, until opaque and at least 63°C (145°F) in the thickest part. Drain and spread in a shallow container. Cover and refrigerate promptly for about 20 minutes until cold.','Toss the cold drained shrimp with {{dressoil}}, {{dressvinegar}} and {{pepper}}. Fold in {{mayo}}, arrange on a small serving dish and serve chilled.',END],'Both imported entries reproduce the same original recipe 4. Its reference to recipe 3 includes oil, vinegar, pepper and optional salt before the mayonnaise; those seasonings are expanded here, with no additional dressing salt beyond the poaching water and mayonnaise. A modern 125 g raw shrimp quantity is intended to yield roughly the original 100 g cooked portion. The original two tablespoons mayonnaise become 30 ml.');finish(r);homemade(r)
s=src(43);aliases[s['id']]=dict(id=s['id'],canonicalId=r['id'],bodySha256=s['bodySha256'],reason='Same single original Dutch recipe 4, including the identical recipe-3 preparation reference and 100 g shrimp with about two tablespoons mayonnaise.');r['sourceAliases'].append(s['id']);r['source']+=' Equivalent source retained: '+s['recipe']['source'];records.pop(s['id'],None);merges=[s]

r=add(44,'Haring met Mayonnaise — Cured Herring Platter',2,10,'Ready-to-eat cured herring is cut into diagonal pieces and topped with mayonnaise.',[I('herring',200,'g','commercial ready-to-eat salt-cured herring fillets, skin and bones removed','Use the same weight of drained ready-to-eat pickled herring; the flavor will be more acidic.'),mayo(45)],['Keep {{herring}} refrigerated until preparing the platter. Check the fillets carefully and remove any remaining pin bones. Pat dry if wet; follow any preparation directions on the ready-to-eat product.','Cut the fillets diagonally into bite-size pieces and arrange on a small platter. Spoon {{mayo}} over the fish and serve chilled.','Refrigerate promptly at 4°C (40°F) or colder and use within 2 days or the herring package’s shorter limit. Do not leave at room temperature for more than 2 hours, or 1 hour above 32°C (90°F).'],'The original two salted herrings become a modern 200 g prepared fillet portion. The source reference soaks whole salted fish in milk and water before gutting, skinning and slicing. Commercial ready-to-eat boneless cured fillets replace that preparation; this is not a method for making raw fresh herring edible by brief salting. The three tablespoons mayonnaise are retained as 45 ml.');r['category']='Fish';homemade(r)

r=add(45,'Dutch Lobster Platter with Lettuce and Mayonnaise',4,100,'Chilled lobster meat is arranged with lettuce, mayonnaise and a toasted-bread centerpiece beneath the decorative head shell.',[I('lobster',900,'g','whole raw lobster, freshly and humanely dispatched by the fishmonger, kept chilled','Use a similar-sized commercially cooked whole lobster; omit poaching and follow its package storage instructions.'),water(3000),I('brothsalt',45,'g','salt for the lobster water','Reduce to taste.'),I('lettuce',2,'','small lettuce heads, about 120 g each','Use the same total weight of romaine hearts.'),I('bread',80,'g','firm white bread, cut into thick slices','Use the same weight of gluten-free bread.'),mayo(120)],['Bring {{water}} and {{brothsalt}} to a boil in a pot large enough for {{lobster}}. Lower in the lobster and return to a gentle boil. Cook for about 18–22 minutes for this size, until the thickest tail meat is opaque and reaches 63°C (145°F).','Lift out and drain. When cool enough to handle, separate the claws and tail, crack or cut the shells and remove the meat. Remove the dark tail vein. Open the head shell and discard the gills, stomach sac, intestines and green internal organs. Keep the clean empty head shell only for the decorative presentation. Check all edible meat for shell fragments.','Spread the meat in a shallow container and refrigerate promptly, within 2 hours of cooking, until cold, about 45–60 minutes. Keep the decorative shell chilled separately.','Separate, wash and thoroughly dry {{lettuce}}. Toast {{bread}} until crisp, then cool. Arrange the toast in the middle of a platter and rest the clean head shell on it; arrange lettuce leaves around the toast, keeping some lettuce for a side bowl.','Place the cold lobster meat on the lettuce and spoon {{mayo|0.5}} between the pieces. Serve {{mayo|0.5}} separately with the reserved lettuce. The clean shell is decorative; only the lobster meat, bread, lettuce and sauce are eaten.',END],'The full original includes the toasted-bread pedestal, two lettuce heads, separated lobster meat and additional lettuce and mayonnaise on the side. The source explicitly permits buying already-cooked lobster. A modern 900 g raw lobster and measured water, salt, bread and sauce amounts are supplied. Prompt shallow-container chilling replaces leaving a whole cooked lobster warm for an extended period.');finish(r);homemade(r)

r=add(48,'Selderijknol met Mayonnaise — Raw Celeriac Salad',4,35,'Fine strips of raw celeriac are briefly seasoned and drained, then dressed with mayonnaise and parsley.',[I('celeriac',300,'g','peeled celeriac, prepared weight','Use the same weight of peeled kohlrabi for a different flavor.'),salt(.5),I('seasonvinegar',15,'ml','white wine vinegar for resting the celeriac','Use the same volume of lemon juice.'),mayo(45),I('parsley',5,'g','fresh parsley leaves, finely chopped','Use the same weight of chervil.')],['Rinse {{celeriac}}, pat dry and cut into very thin slices, then long fine matchsticks. Toss with {{salt}} and {{seasonvinegar}} in a bowl. Cover and refrigerate for 20 minutes.','Drain in a sieve and gently squeeze out excess liquid. Fold in {{mayo}}, transfer to a serving dish and sprinkle with {{parsley}}. Serve cold.','Cover and refrigerate at 4°C (40°F) or colder and use within 2 days. Stir before serving; the celeriac may release more liquid.'],'Half a celeriac is standardized to a modern 300 g peeled portion. The original raw preparation, seasoning rest and draining are retained. Salt, vinegar, parsley, rest time and yield are supplied. The original three tablespoons mayonnaise become 45 ml.');r['category']='Salads';homemade(r)

r=add(52,'Chicken Finger-Roll Sandwiches with Mayonnaise',8,90,'Finely chopped poached chicken is moistened with a little mayonnaise and chicken broth, then tucked into soft finger rolls.',[I('chicken',450,'g','raw boneless skinless chicken breast','Use the same weight of boneless skinless chicken thigh; poach until fully cooked.'),I('stock',900,'ml','unsalted prepared chicken stock for poaching','Use the same volume of unsalted vegetable stock.'),I('cookedchicken',300,'g','cooked chicken reserved from the poaching step; not an additional purchase','Use 300 g commercially cooked plain chicken for a quicker version and omit raw-chicken poaching.'),I('soup',30,'ml','poaching broth reserved after the chicken is fully cooked','Use the same volume of fresh prepared chicken stock.'),mayo(30),I('rolls',8,'','small soft finger rolls, about 35 g each','Use the same number of small soft sandwich buns.')],['Bring {{stock}} to a gentle simmer in a saucepan. Add {{chicken}} and poach for about 15–20 minutes until the thickest part reaches 74°C (165°F). Lift out and measure {{soup}} from the fully cooked poaching broth into a small clean container.','Measure {{cookedchicken}} from the poached meat. Spread it in a shallow container and refrigerate promptly, along with the reserved broth, until cold, about 45 minutes. Refrigerate any extra cooked meat separately for another dish within 2 days.','Finely chop the cold measured chicken, or pulse briefly in a food processor. Mix with {{mayo}} and the measured cold broth until evenly moistened and soft enough to spread.','Split {{rolls}} lengthwise without cutting all the way through. Divide the chicken filling evenly among them and serve.','Keep filled rolls covered at 4°C (40°F) or colder and use within 1 day. Refrigerate within 2 hours, or within 1 hour above 32°C (90°F).'],'Both imported entries reproduce the same Greenbaum paragraph. The source ratio is one tablespoon each mayonnaise and chicken soup per cup of ground chicken. This modern batch uses two loosely packed cups represented by 300 g cooked chopped chicken, with 30 ml each mayonnaise and broth. The cooked-cup weight is a working estimate, not a universal conversion. Raw chicken is provided in excess to allow for cooking loss; the measured cooked portion is explicit. Finger-roll count, cooking and chilling are supplied.');finish(r);homemade(r,'greenbaum')
s=src(53);aliases[s['id']]=dict(id=s['id'],canonicalId=r['id'],bodySha256=s['bodySha256'],reason='Exact repetition of the single Greenbaum Chicken Sandwiches with Mayonnaise paragraph, including the one-tablespoon-each per cup ratio.');r['sourceAliases'].append(s['id']);r['source']+=' Equivalent source retained: '+s['recipe']['source'];records.pop(s['id'],None);merges.append(s)

r=add(54,'Greenbaum Parsley-Tinted Mayonnaise',12,15,'Strained parsley and lemon juice give mayonnaise a fresh herb flavor and a natural green tint.',[mayo(200),I('parsley',15,'g','fresh parsley leaves, washed and thoroughly dried','Use the same weight of chervil for a different flavor.'),lemon(15)],['Chop {{parsley}} very finely. Pound with {{lemon}} in a mortar until the leaves form a wet paste, or process in a small food processor.','Press through a fine sieve lined with a clean cloth, squeezing to collect the green liquid and leaving the coarse herb fibers behind. Gradually stir the extracted liquid into {{mayo}} until evenly blended. The color varies naturally with the parsley.','Serve as a condiment with cooked chilled foods. Cover and refrigerate at 4°C (40°F) or colder and use within 2 days.'],'The source gives no quantities; all amounts and twelve small condiment servings are modern working estimates. Its chopped, pounded and strained parsley method is retained, rather than simply leaving chopped herbs in the dressing.');homemade(r,'greenbaum')

r=add(57,'Whole Tomatoes with Mayonnaise',4,45,'Peeled, chilled tomatoes sit on lettuce leaves with a tablespoon of mayonnaise over each.',[I('tomatoes',4,'','medium ripe firm tomatoes, about 120 g each','Use similarly sized yellow tomatoes for a different color.'),water(1500),I('lettuce',4,'','large lettuce leaves, washed and dried','Use the same number of romaine leaves.'),mayo(60)],['Bring {{water}} to a boil. Rinse {{tomatoes}}, remove the stem cores and score a shallow cross on the bottom of each. Lower into the water for about 20–40 seconds, just until the skins loosen; avoid cooking the flesh soft.','Lift into a bowl of cold drinking water. When cool enough to handle, peel off the skins, pat dry and refrigerate for about 30 minutes until cold.','Place {{lettuce}} on individual plates. Set a cold peeled tomato on each leaf and divide {{mayo}} evenly over the tomatoes, giving one tablespoon per tomato in this batch. Serve cold.',END],'The original specifies peeling and chilling whole tomatoes and one tablespoon mayonnaise per tomato. Four modern medium tomatoes, cooking water, chilling time and four servings are supplied.');r['category']='Salads';homemade(r,'greenbaum')

assert len(newids)==8,len(newids)
(root/'content-overrides.json').write_text(json.dumps(list(records.values()),ensure_ascii=False,indent=2),encoding='utf-8')
(root/'recipe-aliases.json').write_text(json.dumps(list(aliases.values()),ensure_ascii=False,indent=2),encoding='utf-8')
for id in newids:db.execute('insert or replace into decisions values(?,?,?,?,?)',(id,records[id]['bodySha256'],'prepared-adaptation','Complete dish preparation and measured homemade mayonnaise variation supplied','repair-batch-029.py'))
for s in merges:db.execute('insert or replace into decisions values(?,?,?,?,?)',(s['id'],s['bodySha256'],'prepared-merge',aliases[s['id']]['reason'],'repair-batch-029.py'))
db.commit();print(json.dumps(dict(newAdaptations=len(newids),newMergedSources=len(merges),totalOverrides=len(records),totalAliases=len(aliases))))

